    Concept = s.Concept,
    City = s.City,
    AreaManager = s.AreaManager,
    OperationManager = s.OperationManager,
    Region = s.Region
WHEN NOT MATCHED THEN INSERT (StoreCode, StoreName, Concept, City, AreaManager, OperationManager, Region)
VALUES (s.StoreCode, s.StoreName, s.Concept, s.City, s.AreaManager, s.OperationManager, s.Region);
